// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, bytes memory _data) public {
        vm.assume(_value > 0 && _value <= address(this).balance && _data.length <= 1024);

        Receiver target = new Receiver();

        vm.deal(address(c), _value);

        uint256 balBefore = address(target).balance;

        vm.prank(c.owner());
        c.sendMoney(address(target), _value, _data);

        uint256 balAfter = address(target).balance;

        assertTrue(balAfter - balBefore == _value);
    }
}

contract Receiver {
    receive() external payable {}
    fallback() external payable {}
}
